package net.officefloor.hq.app.holiday;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The holidays on a sheet, earliest first. The signed-in user's name comes in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/holidays")
@Validated
public class HolidayController {

    public record HolidayView(long id, LocalDate date) {

        static HolidayView of(Holiday holiday) {
            return new HolidayView(holiday.getId(), holiday.getDay());
        }
    }

    public record HolidayForm(@NotNull LocalDate date) {
    }

    public record Refusal(String message) {
    }

    private final HolidayService service;

    public HolidayController(HolidayService service) {
        this.service = service;
    }

    @GetMapping
    public List<HolidayView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(HolidayView::of).toList();
    }

    @PostMapping
    public HolidayView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody HolidayForm form) {
        return HolidayView.of(service.add(sheetId.trim(), user.trim(), form.date()));
    }

    @ExceptionHandler(HolidayRefused.class)
    public ResponseEntity<Refusal> refused(HolidayRefused e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new Refusal(e.getMessage()));
    }

    /** Another user added the same date at the same moment: this one is refused. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void taken() {
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

export interface Holiday {
  id: number;
  /** The holiday's date (yyyy-mm-dd). */
  date: string;
}

const DATE = /^\d{4}-\d{2}-\d{2}$/;

// The sheet's holidays, earliest first, and the entry that adds one; no date is on the list twice. A claim's
// due-by, fixed when it is added, counts business days, skipping the weekends and the holidays on the sheet then.
@Component({
  selector: 'app-holidays',
  template: `
    <section aria-label="Holidays">
      <h2>Holidays</h2>
      <ul>
        @for (h of holidays(); track h.id) {
          <li [attr.data-testid]="'holiday-row-' + h.date">{{ h.date }}</li>
        }
      </ul>
      <form (submit)="save($event)" aria-label="Add holiday">
        <label for="holiday-date">Date</label>
        <input
          id="holiday-date"
          type="date"
          data-testid="holiday-date"
          [value]="date()"
          (input)="date.set(value($event)); error.set('')"
        />
        <button type="submit" data-testid="holiday-add">Add holiday</button>
        @if (error()) {
          <p role="alert" data-testid="holiday-error">{{ error() }}</p>
        }
      </form>
    </section>
  `,
})
export class Holidays {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  protected readonly holidays = signal<Holiday[]>([]);
  protected readonly date = signal('');
  protected readonly error = signal('');
  /** A submit still waiting for its answer: another press meanwhile is ignored. */
  private busy = false;

  constructor() {
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      this.holidays.set([]);
      this.date.set('');
      this.error.set('');
      if (sheet) void this.reload(sheet);
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async save(e: Event): Promise<void> {
    e.preventDefault();
    if (this.busy) return;
    this.error.set('');
    const sheet = this.session.sheet();
    if (!sheet) return;
    const date = this.date().trim();
    if (!DATE.test(date)) {
      this.error.set('Enter a date.');
      return;
    }
    if (this.holidays().some((h) => h.date === date)) {
      this.error.set('That date is already a holiday on this sheet.');
      return;
    }
    const headers = { 'X-User': this.session.user() ?? '' };
    this.busy = true;
    try {
      const saved = await firstValueFrom(
        this.http.post<Holiday>(`/api/sheets/${encodeURIComponent(sheet)}/holidays`, { date }, { headers }),
      );
      if (this.session.sheet() !== sheet) return;
      this.holidays.update((hs) => [...hs.filter((h) => h.id !== saved.id), saved].sort((a, b) => a.date.localeCompare(b.date)));
      this.date.set('');
    } catch (err) {
      if (this.session.sheet() !== sheet) return;
      const answer = err instanceof HttpErrorResponse ? err : null;
      const message = answer?.error?.message
        ?? (answer?.status === 409 ? 'That date is already a holiday on this sheet.' : 'Could not add the holiday.');
      this.error.set(message);
    } finally {
      this.busy = false;
    }
  }

  private async reload(sheet: string): Promise<void> {
    const loads = this.session.loads();
    const holidays = await firstValueFrom(this.http.get<Holiday[]>(`/api/sheets/${encodeURIComponent(sheet)}/holidays`));
    if (this.session.sheet() === sheet && this.session.loads() === loads) this.holidays.set(holidays);
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

interface SheetView {
  id: string;
  today: string;
  archived: boolean;
}

// The signed-in user and the active sheet. Every request after sign-in names the user in X-User.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheet = signal<string | null>(null);
  /** The active sheet's own today (yyyy-mm-dd), whatever date the screen shows it as of. */
  private readonly sheetToday = signal<string | null>(null);
  /**
   * The date this screen shows the sheet as of (yyyy-mm-dd), or null for the sheet as it stands. While set,
   * every read is of the sheet as it stood at the end of that date and every change is refused.
   */
  readonly asOf = signal<string | null>(null);
  /** The active sheet's today (yyyy-mm-dd): every date the screen decides on or defaults to; the as-of date while set. */
  readonly today = computed(() => this.asOf() ?? this.sheetToday());
  /** Whether the active sheet is archived: it stays visible and every change to it is refused. */
  readonly archived = signal(false);
  /** Bumped on every sheet load, so what is shown for the sheet is re-read even for the same id. */
  readonly loads = signal(0);

  async signIn(name: string): Promise<void> {
    const res = await firstValueFrom(this.http.post<{ name: string }>('/api/signin', { name }));
    this.sheet.set(null);
    this.sheetToday.set(null);
    this.asOf.set(null);
    this.archived.set(false);
    this.loads.update((n) => n + 1);
    this.user.set(res.name);
  }

  async loadSheet(id: string): Promise<void> {
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    );
    this.sheet.set(res.id);
    this.sheetToday.set(res.today);
    this.archived.set(res.archived);
    if (this.asOf() !== null) await this.readShown(res.id);
    this.loads.update((n) => n + 1);
  }

  /** Show the active sheet as of a date (yyyy-mm-dd), or as it stands (null): everything shown is re-read. */
  async setAsOf(date: string | null): Promise<void> {
    this.asOf.set(date);
    const id = this.sheet();
    if (id) await this.readShown(id);
    this.loads.update((n) => n + 1);
  }

  /** Re-read whether the sheet is archived, as it is shown (as of the as-of date while one is set). */
  private async readShown(id: string): Promise<void> {
    const res = await firstValueFrom(this.http.get<SheetView>(`/api/sheets/${encodeURIComponent(id)}`));
    if (this.sheet() === res.id) this.archived.set(res.archived);
  }

  async setToday(today: string): Promise<void> {
    const id = this.sheet();
    if (!id) return;
    const res = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    );
    if (this.sheet() === res.id) this.sheetToday.set(res.today);
  }

  async archive(): Promise<void> {
    const id = this.sheet();
    if (!id) return;
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    );
    if (this.sheet() === res.id) this.archived.set(res.archived);
  }
}
